def jump(self, nums: list[int]) -> int:
    n = len(nums)
    dp = [float('inf')] * n
    dp[0] = 0
    for i in range(n):
        if dp[i] == float('inf'):
            continue
        far = min(i + nums[i], n - 1)
        for j in range(i + 1, far + 1):
            dp[j] = min(dp[j], dp[i] + 1)
    return dp[n - 1]

